CREATE TYPE "ChangeLifecycle" AS ENUM ('DRAFT','SUBMITTED','IMPACT_ANALYZING','RISK_ASSESSING','PLAN_GENERATED','REVIEW_REQUIRED','APPROVAL_REQUIRED','APPROVED','REHEARSAL_REQUIRED','REHEARSING','REHEARSAL_CERTIFIED','READY_FOR_RELEASE','RELEASE_WINDOW_OPEN','DEPLOYING','POST_DEPLOYMENT_VALIDATING','VERIFIED','CERTIFIED','REJECTED','BLOCKED','ABORTED','ROLLED_BACK','ROLLBACK_FAILED','FAILED','EXPIRED','SUPERSEDED','CANCELLED');CREATE TYPE "ChangeRisk" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL','PROHIBITED');CREATE TYPE "ChangeApprovalDecision" AS ENUM ('APPROVED','REJECTED','EXPIRED');CREATE TYPE "ChangeRehearsalStatus" AS ENUM ('REQUIRED','RUNNING','CERTIFIED','FAILED','BLOCKED','EXPIRED');CREATE TYPE "ChangeReleaseStatus" AS ENUM ('PLANNED','WINDOW_OPEN','DEPLOYING','VALIDATING','VERIFIED','HALTED','ROLLED_BACK','FAILED','CLOSED');CREATE TYPE "ChangeValidationResult" AS ENUM ('PASS','FAIL','UNKNOWN');CREATE TYPE "ChangeCertificationStatus" AS ENUM ('CERTIFIED','STALE','REVOKED','FAILED');CREATE TYPE "ChangeEvidenceType" AS ENUM ('IMPACT_ANALYSIS','POLICY_DECISION','APPROVAL','GRAPH_SNAPSHOT','REHEARSAL','SIMULATION','DEPLOYMENT','TEST','MONITORING','SLO','RECONCILIATION','SECURITY','PRIVACY','COST','ROLLBACK','CERTIFICATION');CREATE TABLE "ChangeRequest" (id UUID NOT NULL,stableId VARCHAR(200) NOT NULL,title VARCHAR(240) NOT NULL,purpose VARCHAR(2000) NOT NULL,rationale VARCHAR(2000) NOT NULL,scope JSONB NOT NULL,targets JSONB NOT NULL,category VARCHAR(64) NOT NULL,urgency VARCHAR(40) NOT NULL,environment VARCHAR(80) NOT NULL,requestedWindow VARCHAR(120),requesterId VARCHAR(120) NOT NULL,ownerId VARCHAR(120) NOT NULL,businessImpact JSONB NOT NULL,customerImpact JSONB NOT NULL,technicalImpact JSONB NOT NULL,rollbackStrategy VARCHAR(2000) NOT NULL,validationStrategy VARCHAR(2000) NOT NULL,requiredApprovals JSONB NOT NULL,status "ChangeLifecycle" NOT NULL DEFAULT 'DRAFT',risk "ChangeRisk" NOT NULL DEFAULT 'LOW',revision INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,policyVersion VARCHAR(80) NOT NULL,correlationId VARCHAR(120) NOT NULL,createdAt TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,updatedAt TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChangeRequest_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeRiskAssessment" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,risk "ChangeRisk" NOT NULL,reasons JSONB NOT NULL,signals JSONB NOT NULL,methodologyVersion VARCHAR(255) NOT NULL,confidence VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeRiskAssessment_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeImpact" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,directAffected JSONB NOT NULL,indirectAffected JSONB NOT NULL,transitiveAffected JSONB NOT NULL,unknownAffected JSONB NOT NULL,customerImpact JSONB NOT NULL,operationalImpact JSONB NOT NULL,financialImpact JSONB NOT NULL,securityImpact JSONB NOT NULL,privacyImpact JSONB NOT NULL,reliabilityImpact JSONB NOT NULL,performanceImpact JSONB NOT NULL,capacityImpact JSONB NOT NULL,dataIntegrityImpact JSONB NOT NULL,providerImpact JSONB NOT NULL,architecturalImpact JSONB NOT NULL,blastRadius "ChangeRisk" NOT NULL,confidence VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeImpact_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangePlan" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,version INTEGER NOT NULL,status VARCHAR(255) NOT NULL,executionMode VARCHAR(255) NOT NULL,steps JSONB NOT NULL,planHash VARCHAR(255) NOT NULL,generatedBy VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangePlan_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeApproval" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,actorId VARCHAR(255) NOT NULL,approvalType VARCHAR(255) NOT NULL,decision "ChangeApprovalDecision" NOT NULL,revision INTEGER NOT NULL,policyVersion VARCHAR(255) NOT NULL,evidenceHash VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeApproval_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeRehearsal" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,status "ChangeRehearsalStatus" NOT NULL,environment VARCHAR(255) NOT NULL,simulationOnly BOOLEAN DEFAULT true NOT NULL,requestedBy VARCHAR(255) NOT NULL,certifiedBy VARCHAR(255) NOT NULL,certifiedAt VARCHAR(255) NOT NULL,result VARCHAR(255) NOT NULL,correlationId VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeRehearsal_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeRelease" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,status "ChangeReleaseStatus" NOT NULL,releaseReference VARCHAR(255) NOT NULL,windowReference VARCHAR(255) NOT NULL,authorizedBy VARCHAR(255) NOT NULL,lastActorId VARCHAR(255) NOT NULL,deploymentReference VARCHAR(255) NOT NULL,correlationId VARCHAR(255) NOT NULL,startedAt VARCHAR(255) NOT NULL,validatedAt VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeRelease_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeValidation" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,result "ChangeValidationResult" NOT NULL,checks JSONB NOT NULL,validatedBy VARCHAR(255) NOT NULL,correlationId VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeValidation_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeRollback" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,trigger VARCHAR(255) NOT NULL,reason VARCHAR(255) NOT NULL,action VARCHAR(255) NOT NULL,result VARCHAR(255) NOT NULL,actorId VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeRollback_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeEvidence" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,evidenceType "ChangeEvidenceType" NOT NULL,source VARCHAR(255) NOT NULL,reference VARCHAR(255) NOT NULL,integrityHash VARCHAR(255) NOT NULL,payload JSONB NOT NULL,immutable BOOLEAN DEFAULT true NOT NULL,capturedBy VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeEvidence_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeCertification" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,status "ChangeCertificationStatus" NOT NULL,version INTEGER NOT NULL,policyVersion VARCHAR(255) NOT NULL,graphSnapshotId VARCHAR(255) NOT NULL,rehearsalReference VARCHAR(255) NOT NULL,validationEvidence JSONB NOT NULL,deploymentEvidence JSONB NOT NULL,approvalEvidence JSONB NOT NULL,certifiedBy VARCHAR(255) NOT NULL,validUntil TIMESTAMP(3) NOT NULL,invalidationConditions JSONB NOT NULL,invalidationReason VARCHAR(255) NOT NULL,certifiedAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeCertification_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeGraphSnapshot" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,graphVersion VARCHAR(255) NOT NULL,graphFreshness VARCHAR(255) NOT NULL,unresolvedNodes JSONB NOT NULL,unresolvedRelationships JSONB NOT NULL,confidence VARCHAR(255) NOT NULL,staleDependencies JSONB NOT NULL,unknownDependencies JSONB NOT NULL,snapshot JSONB NOT NULL,integrityHash VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeGraphSnapshot_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeDependencySnapshot" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,version VARCHAR(255) NOT NULL,dependencies JSONB NOT NULL,unknownDependencies JSONB NOT NULL,capturedAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeDependencySnapshot_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeDecision" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,decision VARCHAR(255) NOT NULL,actorId VARCHAR(255) NOT NULL,fromStatus VARCHAR(255) NOT NULL,toStatus VARCHAR(255) NOT NULL,revision INTEGER NOT NULL,correlationId VARCHAR(255) NOT NULL,evidenceHash VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeDecision_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangePolicyDecision" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,policyVersion VARCHAR(255) NOT NULL,decision VARCHAR(255) NOT NULL,matchedRules JSONB NOT NULL,failedRules JSONB NOT NULL,evaluatorVersion VARCHAR(255) NOT NULL,actorId VARCHAR(255) NOT NULL,correlationId VARCHAR(255) NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangePolicyDecision_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeObservation" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,metric VARCHAR(255) NOT NULL,status VARCHAR(255) NOT NULL,value JSONB NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeObservation_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeIncident" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,incidentReference VARCHAR(255) NOT NULL,causalityConfidence VARCHAR(255) NOT NULL,details JSONB NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeIncident_pkey" PRIMARY KEY ("id"));\nCREATE TABLE "ChangeLock" ("id" UUID NOT NULL,id VARCHAR(255) DEFAULT gen_random_uuid() NOT NULL,changeRequestId VARCHAR(255) NOT NULL,scope VARCHAR(255) NOT NULL,ownerId VARCHAR(255) NOT NULL,expiresAt TIMESTAMP(3) NOT NULL,heartbeatAt VARCHAR(255) NOT NULL,status VARCHAR(255) DEFAULT 'ACTIVE' NOT NULL,createdAt TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP NOT NULL,CONSTRAINT "ChangeLock_pkey" PRIMARY KEY ("id"));\nALTER TABLE "ChangeRiskAssessment" ADD CONSTRAINT "ChangeRiskAssessment_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeImpact" ADD CONSTRAINT "ChangeImpact_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangePlan" ADD CONSTRAINT "ChangePlan_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeApproval" ADD CONSTRAINT "ChangeApproval_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeRehearsal" ADD CONSTRAINT "ChangeRehearsal_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeRelease" ADD CONSTRAINT "ChangeRelease_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeValidation" ADD CONSTRAINT "ChangeValidation_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeRollback" ADD CONSTRAINT "ChangeRollback_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeEvidence" ADD CONSTRAINT "ChangeEvidence_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeCertification" ADD CONSTRAINT "ChangeCertification_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeGraphSnapshot" ADD CONSTRAINT "ChangeGraphSnapshot_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeDependencySnapshot" ADD CONSTRAINT "ChangeDependencySnapshot_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeDecision" ADD CONSTRAINT "ChangeDecision_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangePolicyDecision" ADD CONSTRAINT "ChangePolicyDecision_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeObservation" ADD CONSTRAINT "ChangeObservation_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeIncident" ADD CONSTRAINT "ChangeIncident_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nALTER TABLE "ChangeLock" ADD CONSTRAINT "ChangeLock_changeRequestId_fkey" FOREIGN KEY ("changeRequestId") REFERENCES "ChangeRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE;\nCREATE UNIQUE INDEX "ChangeRequest_stableId_key" ON "ChangeRequest"("stableId");CREATE INDEX "ChangeRequest_status_risk_updatedAt_idx" ON "ChangeRequest"("status","risk","updatedAt");CREATE INDEX "ChangeRequest_environment_category_idx" ON "ChangeRequest"("environment","category");ALTER TABLE "ChangeCertification" ADD CONSTRAINT "ChangeCertification_graphSnapshotId_fkey" F